runners = [
    {"name": "hosted-1", "labels": {"linux", "x64"}, "busy": False},
    {"name": "self-hosted-gpu", "labels": {"linux", "x64", "gpu"}, "busy": False},
    {"name": "hosted-2", "labels": {"linux", "x64"}, "busy": True},
]

def assign(job_labels, pool):
    for r in pool:
        if not r["busy"] and job_labels.issubset(r["labels"]):
            r["busy"] = True
            return r["name"]
    return None

jobs = [
    ("build", {"linux", "x64"}),
    ("train-model", {"linux", "x64", "gpu"}),
    ("lint", {"linux", "x64"}),
]

for job_name, labels in jobs:
    assigned = assign(labels, runners)
    print(f"{job_name} -> {assigned or 'sin runner disponible'}")
